def list_commands(category=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0527000" if __import__("os").path.isdir("./environment_mix/0527000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_commands"

    def _log(status, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        row = {
            "id": f"T{len(traces)+1:06d}",
            "trace_id": f"api:{endpoint}:{ts}:{len(traces)+1}",
            "parent_id": None,
            "project_name": "data-preprocessing",
            "op_name": endpoint,
            "display_name": endpoint,
            "started_at": ts,
            "ended_at": ts,
            "status": "success" if status == "success" else "error",
            "latency_ms": latency_ms,
            "costs": {"prompt_tokens_total_cost": 0.0, "completion_tokens_total_cost": 0.0, "total_cost": 0.0},
            "attributes": {"model_name": "local", "token_count": 0},
        }
        if error_code:
            row["attributes"]["error_code"] = error_code
        traces.append(row)
        _save("traces.json", traces)

    traces = _load("traces.json")
    if not isinstance(traces, list):
        traces = []

    # Validation
    if category is not None:
        if not isinstance(category, str):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "category must be a string when provided.")
        if category.strip() == "":
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "category cannot be empty when provided.")

    commands = _load("commands.json")
    if not isinstance(commands, list):
        commands = []

    out = []
    if category is None:
        out = [{"name": c.get("name"), "description": c.get("description"), "category": c.get("category")} for c in commands]
    else:
        for c in commands:
            if c.get("category") == category:
                out.append({"name": c.get("name"), "description": c.get("description"), "category": c.get("category")})

    resp = {"data": out, "meta": {"total": len(out), "category": category}}
    _log("success")
    return resp

