                return False
            if username is not None and u.get("username") != username:
                return False
            if email is not None and u.get("email") != email:
                return False
            return True

        out = [u for u in users if isinstance(u, dict) and _match(u)]
        resp = {
            "object": "list",
            "data": out,
            "total": len(out),
            "has_more": False,
            "next_cursor": None,
        }

    # Audit/log to traces (only observable dynamics collection available)
