    return _err("NOT_FOUND", "No project exists with that name.", project_name=project_name)

def list_runs(project_name=None, state=None, user_id=None, min_accuracy=None, max_accuracy=None, min_loss=None, max_loss=None, batch_size=None, epochs=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0527000" if __import__("os").path.isdir("./environment_mix/0527000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status_out = "success"

    # Helper validation for numeric inputs
    def _is_number(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    def _is_int(x):
        return isinstance(x, int) and not isinstance(x, bool)

    # Validate types
    if project_name is not None and not isinstance(project_name, str):
        status_out = "error"
        resp = _err("VALIDATION_ERROR", "project_name must be a string.", project_name=project_name)
    elif state is not None and not isinstance(state, str):
        status_out = "error"
        resp = _err("VALIDATION_ERROR", "state must be a string.", state=state)
    elif user_id is not None and not isinstance(user_id, str):
        status_out = "error"
        resp = _err("VALIDATION_ERROR", "user_id must be a string.", user_id=user_id)
    elif min_accuracy is not None and not _is_number(min_accuracy):
        status_out = "error"
        resp = _err("VALIDATION_ERROR", "min_accuracy must be a number.", min_accuracy=min_accuracy)
    elif max_accuracy is not None and not _is_number(max_accuracy):
        status_out = "error"
        resp = _err("VALIDATION_ERROR", "max_accuracy must be a number.", max_accuracy=max_accuracy)
    elif min_loss is not None and not _is_number(min_loss):
        status_out = "error"
        resp = _err("VALIDATION_ERROR", "min_loss must be a number.", min_loss=min_loss)
    elif max_loss is not None and not _is_number(max_loss):
        status_out = "error"
        resp = _err("VALIDATION_ERROR", "max_loss must be a number.", max_loss=max_loss)
    elif batch_size is not None and not _is_int(batch_size):
        status_out = "error"
        resp = _err("VALIDATION_ERROR", "batch_size must be an integer.", batch_size=batch_size)
    elif epochs is not None and not _is_int(epochs):
        status_out = "error"
        resp = _err("VALIDATION_ERROR", "epochs must be an integer.", epochs=epochs)
    elif (min_accuracy is not None and max_accuracy is not None) and min_accuracy > max_accuracy:
        status_out = "error"
        resp = _err("VALIDATION_ERROR", "min_accuracy cannot be greater than max_accuracy.", min_accuracy=min_accuracy, max_accuracy=max_accuracy)
    elif (min_loss is not None and max_loss is not None) and min_loss > max_loss:
        status_out = "error"
        resp = _err("VALIDATION_ERROR", "min_loss cannot be greater than max_loss.", min_loss=min_loss, max_loss=max_loss)
    else:
        # Aegis CommandOps Registry datastore has no runs collection; interpret "runs" as top-level traces (one per run)
        traces = _load("traces.json")
        if not isinstance(traces, list):
            traces = []

        # Project existence check when supplied (keep lenient: unknown project => empty list, not error)
        allowed_projects = set()
        projects = _load("projects.json")
        if isinstance(projects, list):
            for p in projects:
                if isinstance(p, dict) and isinstance(p.get("name"), str):
                    allowed_projects.add(p["name"])

        def _coerce_num(v):
            if isinstance(v, (int, float)) and not isinstance(v, bool):
                return float(v)
            return None

        out = []
        for tr in traces:
            if not isinstance(tr, dict):
                continue

            # Treat each trace as a run record
            if project_name is not None and tr.get("project_name") != project_name:
                continue

            # "state" filter mapped from trace status; accept common synonyms
            if state is not None:
                st = state.lower()
                tr_status = tr.get("status")
                if st in ("finished", "succeeded", "success"):
                    if tr_status != "success":
                        continue
                elif st in ("failed", "error"):
                    if tr_status != "error":
                        continue
                else:
                    # unsupported states -> refuse rather than partial match
                    status_out = "error"
                    resp = _err("VALIDATION_ERROR", "Unsupported state value.", state=state, supported=["finished", "running", "failed", "success", "error"])
                    break

            # user_id: traces don't have it; if requested, no rows can match
            if user_id is not None:
                continue

            attrs = tr.get("attributes") if isinstance(tr.get("attributes"), dict) else {}
            accuracy = _coerce_num(attrs.get("accuracy"))
            loss = _coerce_num(attrs.get("loss"))
            bsz = attrs.get("batch_size")
            eps = attrs.get("epochs")

            if min_accuracy is not None:
                if accuracy is None or accuracy < float(min_accuracy):
                    continue
            if max_accuracy is not None:
                if accuracy is None or accuracy > float(max_accuracy):
                    continue
            if min_loss is not None:
                if loss is None or loss < float(min_loss):
                    continue
            if max_loss is not None:
                if loss is None or loss > float(max_loss):
                    continue
            if batch_size is not None:
                if not (isinstance(bsz, int) and not isinstance(bsz, bool)) or bsz != batch_size:
                    continue
            if epochs is not None:
                if not (isinstance(eps, int) and not isinstance(eps, bool)) or eps != epochs:
                    continue

            out.append(tr)

        if status_out == "success":
            resp = {
                "object": "list",
                "data": out,
                "total": len(out),
                "has_more": False,
                "next_cursor": None,
            }

    # Audit/log to traces (self-log; appended regardless of outcome)
    try:
        traces2 = _load("traces.json")
        if not isinstance(traces2, list):
            traces2 = []
        now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        latency_ms = int((time.time() - t0) * 1000)
        traces2.append({
            "id": f"call_{len(traces2):06d}",
            "trace_id": f"call_{len(traces2):06d}",
            "parent_id": None,
            "project_name": "data-preprocessing",
            "op_name": "list_runs",
            "display_name": "list_runs",
            "started_at": now,
            "ended_at": now,
            "status": "success" if status_out == "success" else "error",
            "latency_ms": latency_ms,
            "costs": {
                "prompt_tokens_total_cost": 0.0,
                "completion_tokens_total_cost": 0.0,
                "total_cost": 0.0
            },
            "attributes": {
                "model_name": "tool",
                "token_count": 0
            }
        })
        _save("traces.json", traces2)
    except Exception:
        if "error" in resp:
            resp["error"].setdefault("audit", "failed")
        else:
            resp.setdefault("audit", "failed")

    return resp

