    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status_out = "success"

    # Validate
    if project_name is not None and not isinstance(project_name, str):
        status_out = "error"
        resp = _err("VALIDATION_ERROR", "project_name must be a string.", project_name=project_name)
    elif status is not None and (not isinstance(status, str) or status not in ("success", "error")):
        status_out = "error"
        resp = _err("VALIDATION_ERROR", "status must be one of: success, error.", status=status)
    elif parent_id is not None and not isinstance(parent_id, str):
        status_out = "error"
        resp = _err("VALIDATION_ERROR", "parent_id must be a string.", parent_id=parent_id)
