        status_out = "error"
        resp = _err("VALIDATION_ERROR", "op_name_contains must be a string.", op_name_contains=op_name_contains)
    else:
        # Validate parent_id "identifier" loosely: allow typical IDs like T000001, call_000001, UUID-ish, etc.
        if parent_id is not None:
