    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_trace"
    traces = _load("traces.json")
    if not isinstance(traces, list):
        traces = []

    def _log(status, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        row = {
            "id": f"T{len(traces)+1:06d}",
            "trace_id": f"api:{endpoint}:{ts}:{len(traces)+1}",
            "parent_id": None,
            "project_name": "data-preprocessing",
            "op_name": endpoint,
            "display_name": endpoint,
            "started_at": ts,
            "ended_at": ts,
            "status": "success" if status == "success" else "error",
            "latency_ms": latency_ms,
            "costs": {"prompt_tokens_total_cost": 0.0, "completion_tokens_total_cost": 0.0, "total_cost": 0.0},
            "attributes": {"model_name": "local", "token_count": 0},
        }
        if error_code:
            row["attributes"]["error_code"] = error_code
        traces.append(row)
        _save("traces.json", traces)

    if not isinstance(trace_id, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "trace_id must be a string.")
    if trace_id.strip() == "":
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "trace_id cannot be empty.")
    try:
        uuid.UUID(trace_id)
    except ValueError:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "trace_id must be a valid UUID.", trace_id=trace_id)

    # traces.json in this datastore contains span-like rows; trace_id groups them.
    matched = [t for t in traces if t.get("trace_id") == trace_id]
    if not matched:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "No trace exists with that id.", trace_id=trace_id)

    # Return the first record plus related spans.
    resp = {"data": {"trace_id": trace_id, "spans": matched}, "meta": {"total_spans": len(matched)}}
    _log("success")
    return resp
